import{_ as r}from"./chunks/5e9b3a79797b0d635c5a.DV-bj4dx.js";import{_ as l,C as i,o as p,c as o,j as t,a as n,E as s,a5 as h}from"./chunks/framework.DNkHA0lr.js";const T=JSON.parse('{"title":"如果你想在未来10年蓬勃发展，请学习这项技能","description":"","frontmatter":{"title":"如果你想在未来10年蓬勃发展，请学习这项技能","originalTitle":"Learn This Skill If You Want To Thrive In The Next 10 Years","date":"2022-08-13","originalUrl":"https://thedankoe.com/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years/","minutes":13,"sourceHash":"6ad0b855211141046208b4aaceedd1e8214bac8941de540f585086c494dd5ddb","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years/"}]]},"headers":[],"relativePath":"letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years.md","filePath":"letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years.md"}'),u={name:"letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years.md"};function d(c,e,m,f,b,g){const a=i("ArticleMeta");return p(),o("div",null,[e[0]||(e[0]=t("h1",{id:"如果你想在未来10年蓬勃发展-请学习这项技能",tabindex:"-1"},[n("如果你想在未来10年蓬勃发展，请学习这项技能 "),t("a",{class:"header-anchor",href:"#如果你想在未来10年蓬勃发展-请学习这项技能","aria-label":'Permalink to "如果你想在未来10年蓬勃发展，请学习这项技能"'},"​")],-1)),s(a),e[1]||(e[1]=h('<p><a href="https://www.youtube.com/embed/N8U5bzSD65Q?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>从我记事起，我就一直把做自己热爱的事作为谋生目标。难道这不是每个人都想要的吗？</p><p>我的家人、老师，甚至我在网上关注的人，都冲我大喊大叫，极力劝我走其他的路。</p><p>所以我就照做了。</p><ul><li>上了大学，但整天都在参加派对</li><li>在业余时间学习创意技能</li><li>创办了能想到的所有在线业务</li><li>学习编程，因为听说这很“赚钱”</li><li>从大学退学，因为那是在浪费我的时间</li><li>在一家设计机构找了一份年薪5.5万美元的初级网页开发工程师工作</li></ul><p>在这整个旅程中，“做我热爱的事”的梦想一直萦绕在我的脑海深处。我不断地被它提醒。从16岁到25岁，没有哪一刻我不是在做着有意义的副业项目。</p><p>时至今日，我依然保持着这个习惯。如果不是商业项目，那就是健康项目。这就是我走出困境的方法，因为我陷入困境的唯一原因是精神熵（psychic entropy），即大脑趋向于无序。这意味着我没有一个能让我集中注意力的目标、项目或优先事项。当我花时间思考一个我想要取得进展的领域时，一段时间后，我的脑海中就会浮现出一个愿景。结果呢？我的生活质量大幅提升。前提是，我立即对那个愿景采取行动。</p><p>我目前的项目是我的新写作产品，以及在长时间不练之后，让我在健身房的复合举重成绩恢复到之前的水平。出于某种原因，我<em>真的</em>想达到600磅的硬拉，即便我几年前曾发誓再也不练硬拉了。这听起来就是很好玩，撇开风险不谈（而且风险增加了乐趣，也增加了保持健康习惯的必要性）。</p><p>为什么我要告诉你这些？</p><p>因为我意识到，根本没人知道自己在说什么。我当时在听取那些并未实现我想要成就的人的职业和生活建议。在他们封闭的思想中，我想要创造的现实是不可能的，然而为了保持理智，我却不断地循环回到我热爱从事的项目上。</p><p>也就是说，如果我能找到一种方法，将这些“激情项目”变现，那我就稳了。</p><p>在对人们让你学习的每一项“热门技能”进行了数年的试错之后，我发现了这个秘密。</p><h2 id="为什么是写作" tabindex="-1">为什么是写作？ <a class="header-anchor" href="#为什么是写作" aria-label="Permalink to &quot;为什么是写作？&quot;">​</a></h2><p><a href="https://open.spotify.com/embed/episode/0HLHWwyXRJtLYFFYH6GfdE?si=76beae14d2344f23&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>互联网的后端是代码。互联网的前端是媒体。如果你想在未来蓬勃发展，掌握代码或媒体是你最好的选择。如果你能掌握——或者建立一个团队——来充分利用这两者（比如为一个<strong>软件</strong>公司做<strong>营销</strong>），你就完全不必担心你的人生方向。</p><p>也就是说，能够利用媒体和代码<em>双重</em>杠杆。有了建站工具、会员面板、邮件发送平台以及其他让一人企业（one-person business）模式成为可能的无代码工具，这不仅是可能的，更是轻而易举的。</p><p>难道你没看到其中的威力吗？这难道<em>没有</em>为你注入巨大的能量，去学习你能接触到的所有东西吗？既然你能利用代码杠杆并学习媒体，在传播你热爱的理念的同时建立你的微型帝国，为什么你还没有开始在创业中去试错摸爬滚打？</p><p>我在大学里学了编程，但我对成为一名程序员毫无兴趣。我想做自由职业者。所以我努力去尝试了。网页设计、SEO、Facebook广告、内容营销、数字艺术，以及天底下的每一种技能……除了一个。</p><p>我在所有这些商业模式上都失败了，这是有原因的。我不明白人们真正想买的是什么。不仅如此，我还不知道如何让他们购买我提供的东西。就在那时，我发现了Twitter。人们在谈论在线业务和自我提升。我深深地陷了进去。</p><p>一些发布电子商务见解的账号提到了一项名为“文案写作（copywriting）”的技能。当我深入研究时，那似乎正是我缺少的一环。在我看来，文案写作就是具有说服力的写作。想一想营销和销售——这两项最重要的高收入技能——只不过是以书面形式呈现。</p><p>正如你能猜到的那样，这就是我通向成功所缺失的一环。我开始在Twitter上写作来练习我的文笔，从失败中吸取教训，并在多个平台上积累了35万的受众粉丝。</p><h3 id="重申一遍-为什么是写作" tabindex="-1">重申一遍，为什么是写作？ <a class="header-anchor" href="#重申一遍-为什么是写作" aria-label="Permalink to &quot;重申一遍，为什么是写作？&quot;">​</a></h3><p>媒体是互联网的前端。它是你在海量的自嘲梗和毫无价值的内容中获取、留住并转化注意力的方式。</p><p><img src="'+r+'" alt=""></p><p>媒体的基础是写作。</p><ul><li><strong>推文（Tweets）？</strong> 写作。</li><li><strong>长推（Threads）？</strong> 写作。</li><li><strong>时事通讯（Newsletters）？</strong> 写作。</li><li><strong>博客文章（Blog posts）？</strong> 写作。</li><li><strong>冷邮件（Cold emails）？</strong> 写作。</li><li><strong>任何形式的广告（Ads of any form）？</strong> 始于写作。</li><li><strong>YouTube视频（YouTube videos）？</strong> 依靠写好的脚本才能做到最好。</li><li><strong>Instagram短视频和TikTok（Instagram reels and TikToks）？</strong> 就像阅读写得很好的推文。</li><li><strong>Instagram上的图片（Images on Instagram）？</strong> 通常是围绕一句写得很好的名言或短语设计的。</li><li><strong>任何其他形式的在线营销、广告或娱乐（Any other form of online marketing, advertising, or entertainment）？</strong> 始于写作。</li></ul><p>在Instagram的互动量和粉丝增长方面，我能跑赢每一个拥有六块腹肌的老哥，这是有原因的。</p><p>高影响力的数字写作。</p><p>如果你想成为媒体大师（并利用无代码工具作为杠杆分发你的作品并吸引受众），很明显，写作必须成为你一人企业的基础。</p><p><strong>在我们深入探讨之前：</strong>《2小时创作者》（2 Hour Writer）现已开启预售。如果你是一位有抱负的作家、一人企业所有者，或者是想要实施我的内容生态系统的创作者（creator）——<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">在发布日之前，你可以点击这里享受六折优惠。</a></p><h2 id="开启一人写作企业的9个步骤" tabindex="-1">开启一人写作企业的9个步骤 <a class="header-anchor" href="#开启一人写作企业的9个步骤" aria-label="Permalink to &quot;开启一人写作企业的9个步骤&quot;">​</a></h2><p>我称自己为作家，因为这就是我的日常工作（哪怕在社交媒体上看起来并不像）。</p><p>通过撰写推文、时事通讯和长推，并将它们重新二次制作为Instagram帖子、YouTube视频、LinkedIn帖子及其他内容，我维持着每月4万到6万美元的收入。</p><p>回想起来，正如此信开头提到的，写作是一个力量倍增器，它帮我每个月都能赚到我以前的薪水金额。</p><p>但是，如果把一切都剥离，只剩下Twitter和一份时事通讯，我依然能维持85-90%的收入。我很少在其他平台上做推广，哪怕有也很少。我目前正在建立杠杆和跨平台权威。</p><p>言归正传，以下是开启你的写作业务的9个步骤。</p><h3 id="_1-选择一个你滔滔不绝的话题" tabindex="-1">1) 选择一个你滔滔不绝的话题 <a class="header-anchor" href="#_1-选择一个你滔滔不绝的话题" aria-label="Permalink to &quot;1) 选择一个你滔滔不绝的话题&quot;">​</a></h3><p>选择话题是每个人在内容创作时都会感到挣扎的事情。让我把它变得简单点。</p><p>写下：</p><ul><li>你最喜欢的书</li><li>你最近的YouTube观看历史</li><li>你最喜欢的社交媒体账号</li><li>如果钱不是问题，你会写些什么</li></ul><p>说真的，拿出一张纸（或者手机里的备忘录应用），把这些都写下来。</p><p>我们为什么要这么做？</p><p>因为好的写作不在于有多专业。它关乎能量传递。当你每天兴奋地坐下来写作时，那种能量就会在你的文字中显现出来。</p><h3 id="_2-头脑风暴你的独特视角" tabindex="-1">2) 头脑风暴你的独特视角 <a class="header-anchor" href="#_2-头脑风暴你的独特视角" aria-label="Permalink to &quot;2) 头脑风暴你的独特视角&quot;">​</a></h3><p>新颖性吸引注意力。如果你想让人阅读你写的东西，注意力是必备的前提。</p><p>新颖的视角是吸引注意力最好（且可复制的）方式。</p><p>你该如何想出一个新颖的视角？</p><p>把脑子里的想法倒出来：</p><ul><li>与该话题相关的常见问题</li><li>克服这些问题的好处</li><li>与该话题相关的常见目标</li><li>实现这些目标的绊脚石</li><li>你拥有过的个人经历</li></ul><p>现在，把所有的东西拼凑在一起，然后<em>用跟朋友聊天时的方式把它解释出来。</em></p><p>不要试图去抄袭别人的视角或措辞方式。用你自己的声音说出来，并让它<em>随着时间、努力和练习不断精进。</em></p><p>如果你想要一个关于如何做到这一点的引导性挑战，<a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">下载我免费的7天天才灵感挑战（7 days to genius challenge）。</a></p><p>如果你不想经历这些，你可以练习用自己的话解释话题，让经验塑造你的视角。你可以通过一整年每天写推文来做到这一点。看看你能学到什么。</p><h3 id="_3-围绕该话题写1000字以上" tabindex="-1">3) 围绕该话题写1000字以上 <a class="header-anchor" href="#_3-围绕该话题写1000字以上" aria-label="Permalink to &quot;3) 围绕该话题写1000字以上&quot;">​</a></h3><p>互联网上的每一篇内容，都是围绕一个个人问题或专业问题展开的。</p><p>以下是你可以用来构建写作框架的方法。</p><ol><li>解释与该话题相关的问题</li><li>谈谈你对它的个人经历</li><li>可选：给出围绕该问题的背景信息</li><li>给出如何解决该问题的循序渐进、可操作的建议（就像这封信一样）</li></ol><p>在一开始，可操作的建议是你建立受众群体的方式。我不会担心内容是否超级有见地，在人们认识你之前，那对你的增长毫无帮助。</p><p>就像你最喜欢的YouTuber一开始并不是做vlog的。他们从有效的内容起步，建立受众，然后通过做自己想做的任何事来让那个市场饱和度降低。这意味着你可以随时加入（这不仅限于YouTube）。</p><h3 id="_4-注册一个博客和时事通讯软件" tabindex="-1">4) 注册一个博客和时事通讯软件 <a class="header-anchor" href="#_4-注册一个博客和时事通讯软件" aria-label="Permalink to &quot;4) 注册一个博客和时事通讯软件&quot;">​</a></h3><p>我很少使用花里胡哨的销售漏斗，你现在也很少看到我在社交媒体上推广我的产品。</p><p>我使用2小时内容生态系统：</p><ul><li>每周1篇时事通讯</li><li>时事通讯保存在博客上</li><li>每周从时事通讯提取1条长推</li><li>每天3条关于时事通讯话题的推文</li></ul><p>只发短推文的人几乎没有什么权威性，在促成销售和拿下客户时会遇到困难。</p><p>权威性来源于两点之一：<strong>深度或专业知识。</strong></p><p>长篇内容才是赚钱的地方。而不是短推文和社交媒体推广。</p><p>为了简单起见，我会注册Beehiiv、Revue或Substack。我们还不需要什么花哨的自动化功能。我们想要的只是一个能够发送时事通讯、收集电子邮件，并将时事通讯积攒存为博客文章的软件（这是一个没人利用的关键点），这样我们就可以把它们作为迷你推销员或独立的潜在客户诱饵插入到我们的其他内容下面。</p><h3 id="_5-对时事通讯中的可操作部分进行二次创作" tabindex="-1">5) 对时事通讯中的可操作部分进行二次创作 <a class="header-anchor" href="#_5-对时事通讯中的可操作部分进行二次创作" aria-label="Permalink to &quot;5) 对时事通讯中的可操作部分进行二次创作&quot;">​</a></h3><p>我们知道，循序渐进的可操作建议是针对社交媒体增长最对新手友好、也最强大的工具。如果你不知道如何增长，很有可能是因为你从一开始就试图变得太过聪明和有深度——而你真正需要做的，就是提供与你的讨论点相关的可操作建议（并结合这篇时事通讯的第6步）。</p><p>将可操作建议与一篇Twitter长推结合起来，你就有可能在第一次尝试时获得100到1000个粉丝。我总是看到这种情况发生。</p><p>我们该如何让这变得简单？</p><p>把你写的时事通讯中的可操作部分变成一篇Twitter长推。就这么简单。在我的新课程<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时创作者》（2 Hour Writer）</a>中，我确切地展示了该如何做，以确保它写出来能产生最大的影响力。</p><h3 id="_6-学习如何在平台上建立人脉并实现增长" tabindex="-1">6) 学习如何在平台上建立人脉并实现增长 <a class="header-anchor" href="#_6-学习如何在平台上建立人脉并实现增长" aria-label="Permalink to &quot;6) 学习如何在平台上建立人脉并实现增长&quot;">​</a></h3><p>当你开始玩一款游戏时，你不会直接一头扎进去开玩。你会完全不知道自己在干嘛，接着大发脾气，然后退出。</p><p>你在不同的社交平台上尝试获得增长却失败了，原因在于你认为这就像发布好内容一样简单。完全不是这么回事。</p><p>你在社交媒体平台上获得增长的方式是让更多人关注你的主页。你怎么做到这点？</p><ul><li>让别人把你的内容<em>分享</em>给他们的受众</li><li>与粉丝体量相近的账号建立联系，共同成长</li><li>在大号的帖子上发表评论，这样人们就能看到你的评论并点击进入你的主页</li><li>把你的长篇内容（时事通讯）做得足够好，好到让人忍不住去谈论它</li><li>加入一个社群（比如 <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Modern Mastery</a>），去结识和你志同道合的人。</li><li>可选做法（但没你想的那么禁忌）：花钱让大号分享（转发，Instagram 上的快拍分享，甚至只是简单留个言，因为这依然能让你的内容暴露在他们的受众面前）。</li></ul><p>当然，如果你想让人们关注你，你依然需要有优质的内容和一个优化过的主页。</p><p>它被称为<em>社交</em>媒体是有原因的。你必须与他人互动，交朋友，并互相帮助共同成长。</p><p>你可以不这么做，但那会慢得让人极其痛苦，而且你会变成那种整天抱怨社交增长如何不公平的账号之一。不要怨恨玩家，要恨就恨这个游戏。</p><h3 id="_7-把想法变成有影响力的推文" tabindex="-1">7) 把想法变成有影响力的推文 <a class="header-anchor" href="#_7-把想法变成有影响力的推文" aria-label="Permalink to &quot;7) 把想法变成有影响力的推文&quot;">​</a></h3><p>从你的时事通讯和长推文（threads）中，你的脑海应该涌现出大量推文的想法。推文是短小精悍的写作，能让人产生反应。</p><p>我最喜欢的推文写作方式是使用我开发的框架：PPP</p><ul><li>Pull (吸引)</li><li>Perspective (视角)</li><li>Punchline (点睛之笔)</li></ul><p>用一些能引起注意的东西（比如一个数字或百分比）把他们吸引进来，给出一个源于个人经验和批判性思考的独特视角，最后用一种合理的方式做个总结。</p><p>视角和点睛之笔通常是相互联系的，通常表现为下面这样的金句：</p><blockquote><p>人们会花10个小时去担心一项只需10分钟就能完成的任务。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1556598603065475072?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">August 8, 2022</a></p></blockquote><p>你也可以在列表推文中看到这个框架被很好地拆解（当你要给出可操作的建议时请使用这些）：</p><blockquote><p>大多数人会花费：\\</p><p>8小时在别人的梦想上<br> 4小时躲避自己的梦想<br> 2小时走个过场\\</p><p>16小时醒着<br> 24小时睡觉\\</p><p>并不需要花40年时间和一个退休计划，才能意识到拿个参与奖并不能让人满足。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1556571426794127361?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">August 8, 2022</a></p></blockquote><p>这只是众多推文写作方法之一。你最好的做法是研究你在第一步中列出的账号，并遵循<a href="https://thedankoe.com/how-to-copy-your-way-to-success-instead-of-mediocrity/" target="_blank" rel="noreferrer">智能模仿流程</a>。模仿他们的写作，把他们的推文当作辅助轮，剖析它们为什么表现出色，并尝试用你自己的方式进行复刻。</p><h3 id="_8-开发一个写作系统" tabindex="-1">8) 开发一个写作系统 <a class="header-anchor" href="#_8-开发一个写作系统" aria-label="Permalink to &quot;8) 开发一个写作系统&quot;">​</a></h3><p>这期时事通讯回顾了如果我必须从零开始，我会做的所有事情。</p><p>我浪费了2年时间测试销售漏斗、不同的内容写作方法，以及寻找用写作维持高月收入的最佳方式。</p><p>我最好的建议？</p><p>从一开始就创建一个系统，并随着时间的推移不断完善它。然后，如果你以后想把它打包出售，你是可以这么做的。这正是“一人企业”模式在做的事。他们用在自己身上测试过的系统（为了解决自己的问题）取得结果，然后再卖给别人——因为当这个系统达到完美时，你已经有了充足的经验和权威来做背书。</p><p>我使用 Notion 来创建系统，好让自己轻松一点。不需要其他花哨的软件。</p><p>这些系统一开始可以是你每日或每周需要做的事情的逐步列表。然后你就可以开始玩转 Notion 的那些炫酷功能了。</p><h3 id="_9-拓展到其他平台" tabindex="-1">9) 拓展到其他平台 <a class="header-anchor" href="#_9-拓展到其他平台" aria-label="Permalink to &quot;9) 拓展到其他平台&quot;">​</a></h3><p>在很长一段时间里，我都把这件事想得太复杂了。</p><p>凭借我的<em>写作</em>技能，我在 Instagram 上增长到了 23万粉丝，LinkedIn 上有 2.3万，YouTube 上有 7千。</p><p>我获得的互动比那些拥有阿多尼斯般完美身材的哥们儿还要多，因为我的文字比他们线条分明的腹肌更有冲击力。</p><p>我所做的只是复制、粘贴并录制我已经写在时事通讯、长推文和推文中的内容。你甚至可以把你最好的推文变成 TikTok 或 Reels 的脚本。</p><p>先精通 Twitter，获得一些权威，然后利用你最好的推文打入新平台（因为这些想法已经被验证过会有好表现）。</p><h3 id="让我们回顾一下你该如何开启你的写作业务" tabindex="-1">让我们回顾一下你该如何开启你的写作业务 <a class="header-anchor" href="#让我们回顾一下你该如何开启你的写作业务" aria-label="Permalink to &quot;让我们回顾一下你该如何开启你的写作业务&quot;">​</a></h3><p>每天花1-2个小时（考虑到你有自由职业、咨询服务或数字产品，可以通过你正在建立的流量/分发渠道来销售），你能赚到比一些薪水最高的医生还要高的月收入，而且不用在大学学位上花一分钱。</p><p>我们生活在一个追求真实却无人真实的时代。人们不想要专业主义。他们想要个性，想要与“懂他们”的人在一起的归属感。</p><p>我远非最优秀的作家，但我的收入比外面 99% 的作家都要高。事情就是这么有趣。</p><p>以下是我们讨论内容的总结：</p><ul><li>选择一个你滔滔不绝的话题</li><li>头脑风暴出一个你拥有的独特视角</li><li>用结构化的方式写出1000多字</li><li>注册一个时事通讯 / 博客软件并发布它</li><li>将可操作的部分变成一篇爆款 Twitter 长推文</li><li>学习如何建立人脉并让更多人看到你的内容</li><li>把时事通讯里的想法变成推文，并在下方插入你的时事通讯让人“阅读更多”（这会增长你的邮件列表）</li><li>开发一个系统，让每周写作时间不到4-6小时</li><li>准备好后，拓展到其他平台</li></ul><p>最后，如果你有产品或服务，你不会在时间线上直接推销它。</p><p>这就是这个内容生态系统的美妙之处。你在时事通讯中用深度建立权威，将它们作为博客发布，并在那里植入你的产品报价。</p><p>现在，你每天都会在你的推文和长推文下面插入相关的时事通讯。没有推销式的推广，没有在时间线上刷屏发垃圾信息。只有完美的社交媒体增长，以及比你能建立的任何10步销售漏斗带来更多销售额（我测试过了）。</p><h3 id="《两小时作家》上线啦" tabindex="-1">《两小时作家》上线啦！ <a class="header-anchor" href="#《两小时作家》上线啦" aria-label="Permalink to &quot;《两小时作家》上线啦！&quot;">​</a></h3><p>如果你是一个创作者或一人企业，并且想要：</p><ul><li>实施2小时内容生态系统，以实现社交增长并建立权威</li><li>在不依赖模板的情况下产生无限的爆款内容想法</li><li>学会用自己独特的声音写作，让想法有趣到足以让人分享</li></ul><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">那么请在此查看《两小时作家》中包含的其他所有内容。</a></p><p>希望能在里面见到你！</p><p>— Dan “你不需要英语学位也能在互联网上码字” Koe</p><hr><p><a href="/en/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',120))])}const q=l(u,[["render",d]]);export{T as __pageData,q as default};
